import numpy as np

def eig(Nu,r):
    t1=r; t2=1
    L=2*Nu
    H=np.zeros((L,L))
    for i in range(1,Nu+1):
        a=2*i-2; b=2*i-1
        H[a,b]=H[b,a]=-t1
    for i in range(1,Nu):
        b=2*i-1; an=2*i
        H[b,an]=H[an,b]=-t2
    return np.linalg.eigvalsh(H)
for Nu in [2,3,4,5,10,20]:
