/bin/bash -c "python3 - <<'PY'
import numpy as np
from scipy.integrate import quad
ratio=2/3
kF=2*np.pi/5

def q(k): return 1+ratio*np.exp(-1j*k)
def P(k):
    z=q(k); ab=1/np.abs(z)
    # H=-[[0,q],[q*,0]], lower projector
    return np.array([[0.5, 0.5*z*ab],[0.5*np.conj(z)*ab,0.5]],complex)

def C(R,a,b):
    f=lambda k: np.exp(1j*k*R)*P(k)[a,b]
    re=quad(lambda k:f(k).real,-kF,kF,epsabs=1e-13)[0]
    im=quad(lambda k:f(k).imag,-kF,kF,epsabs=1e-13)[0]
    return (re+1j*im)/(2*np.pi)
for label,R,a,b in [('r1 AB0',0,0,1),('r2 AA1',1,0,0),('r3 AB1',1,0,1),('r4 AA2',2,0,0)]:
    c=C(R,a,b)
    print(label,c,abs(c)**2,0.04-abs(c)**2)
print('n',C(0,0,0))
PY"

